CREATE TRIGGER shared_change_sessions_insert AFTER INSERT ON sessions BEGIN INSERT INTO shared_changes(entity,entity_id,operation,instance_id,changed_at) VALUES('sessions',NEW.id,'insert',sengoo_context('instance_id'),CAST(unixepoch('subsec')*1000 AS INTEGER)); END;
