CREATE TRIGGER shared_guard_sessions_insert BEFORE INSERT ON sessions WHEN EXISTS(SELECT 1 FROM shared_executions e WHERE e.session_id=NEW.id AND e.active=1 AND e.owner_instance_id IS NOT COALESCE(sengoo_context('instance_id'),'')) BEGIN SELECT RAISE(ABORT,'shared-session-owned-by-another-instance'); END;
CREATE TRIGGER shared_guard_sessions_update BEFORE UPDATE ON sessions WHEN EXISTS(SELECT 1 FROM shared_executions e WHERE e.session_id=OLD.id AND e.active=1 AND e.owner_instance_id IS NOT COALESCE(sengoo_context('instance_id'),'')) BEGIN SELECT RAISE(ABORT,'shared-session-owned-by-another-instance'); END;
