CREATE TRIGGER shared_message_fence BEFORE UPDATE ON messages WHEN OLD.shared_fence IS NOT NULL AND EXISTS(SELECT 1 FROM shared_executions e WHERE e.session_id=OLD.session_id AND e.active=1 AND e.fence<>OLD.shared_fence) BEGIN SELECT RAISE(ABORT,'stale-execution-fence'); END;
