CREATE TRIGGER shared_change_preferences_update AFTER UPDATE ON app_preferences BEGIN INSERT INTO shared_changes(entity,entity_id,operation,instance_id,changed_at) VALUES('app_preferences',NEW.key,'update',sengoo_context('instance_id'),CAST(unixepoch('subsec')*1000 AS INTEGER)); END;
