CREATE TRIGGER shared_engine_binding_insert AFTER INSERT ON runtime_bindings BEGIN INSERT INTO shared_engine_bindings(session_id,connection_id,engine,native_session_id,synced_revision,generation) VALUES(NEW.session_id,NEW.connection_id,'desktop',NEW.native_session_id,NEW.synced_revision,NEW.generation) ON CONFLICT(session_id,connection_id,engine) DO UPDATE SET native_session_id=excluded.native_session_id,synced_revision=excluded.synced_revision,generation=excluded.generation; END;
CREATE TRIGGER shared_engine_binding_update AFTER UPDATE ON runtime_bindings BEGIN DELETE FROM shared_engine_bindings WHERE session_id=OLD.session_id AND connection_id=OLD.connection_id AND engine='desktop'; INSERT INTO shared_engine_bindings(session_id,connection_id,engine,native_session_id,synced_revision,generation) VALUES(NEW.session_id,NEW.connection_id,'desktop',NEW.native_session_id,NEW.synced_revision,NEW.generation); END;
CREATE TRIGGER shared_engine_binding_delete AFTER DELETE ON runtime_bindings BEGIN DELETE FROM shared_engine_bindings WHERE session_id=OLD.session_id AND connection_id=OLD.connection_id AND engine='desktop'; END;
CREATE TRIGGER shared_message_capture_fence AFTER INSERT ON messages WHEN NEW.shared_fence IS NULL AND EXISTS(SELECT 1 FROM shared_executions e WHERE e.session_id=NEW.session_id AND e.active=1 AND e.owner_instance_id=sengoo_context('instance_id')) BEGIN UPDATE messages SET shared_fence=(SELECT fence FROM shared_executions WHERE session_id=NEW.session_id) WHERE id=NEW.id; END;
